from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test_order")
async def test_order(form_data: str = Form(...), file_data: bytes = File(...)):
    return {"form_data": form_data, "file_data_len": len(file_data)}

client = TestClient(app)

def test_form_before_file():
    # This should have failed with 422 before the fix
    response = client.post(
        "/test_order",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data_len": 5}

def test_file_before_form():
    # This should always have worked
    response = client.post(
        "/test_order",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data_len": 5}

def test_multiple_files():
    @app.post("/test_multiple")
    async def test_multiple(form_data: str = Form(...), file1: bytes = File(...), file2: bytes = File(...)):
        return {"form_data": form_data, "f1": len(file1), "f2": len(file2)}

    response = client.post(
        "/test_multiple",
        data={"form_data": "hello"},
        files={"file1": b"one", "file2": b"two"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "f1": 3, "f2": 3}

